<script setup lang="ts">
import { computed,ref } from 'vue'
import { onLoad,onShow,onHide,onUnload } from '@dcloudio/uni-app'
import FeatureLayout from '../../components/FeatureLayout.vue'
import { api } from '../../services/api'
import type { Story,ProductionOptions,ProductionContext,ProductionTask } from '../../types/domain'
import { errorMessage,goPage,requireSession } from '../../utils/navigation'
const id=ref(''),story=ref<Story|null>(null),options=ref<ProductionOptions|null>(null),context=ref<ProductionContext|null>(null),task=ref<ProductionTask|null>(null)
const voices=ref<Record<string,string>>({}),error=ref(''),busy=ref(false),notes=ref(''),listened=ref(false),watched=ref(false)
let timer:ReturnType<typeof setTimeout>|undefined,visible=true,version=0
const finished=computed(()=>!!task.value&&['awaiting_review','reviewed','failed'].includes(task.value.status))
const changed=computed(()=>!!task.value&&Object.keys(voices.value).some(k=>voices.value[k]!==task.value?.voices[k]))
function stop(){clearTimeout(timer);timer=undefined;version++}
async function poll(){if(!visible||!task.value)return;const request=version;try{const value=await api.productionTask(task.value.id);if(request!==version)return;task.value=value;if(!finished.value)timer=setTimeout(poll,2500)}catch(e){error.value=errorMessage(e)}}
async function load(){if(!id.value||!requireSession())return;error.value='';try{const [s,o,c]=await Promise.all([api.story(id.value),api.productionOptions(),api.productionContext(id.value)]);story.value=s;options.value=o;context.value=c;voices.value=Object.fromEntries(c.roles.map(r=>[r.id,r.voice]));if(s.productionTaskId){task.value=await api.productionTask(s.productionTaskId);voices.value={...task.value.voices};void poll()}}catch(e){error.value=errorMessage(e)}}
async function start(){if(busy.value)return;busy.value=true;error.value='';try{stop();task.value=await api.startProduction(id.value,voices.value,changed.value);listened.value=false;watched.value=false;void poll()}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function retry(){if(!task.value||busy.value)return;busy.value=true;error.value='';try{task.value=await api.retryProduction(task.value.id);void poll()}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function review(kind:'audio'|'visual',decision:'approve'|'changes'){const value=task.value;if(!value?.media?.videoSha256||busy.value)return;if(decision==='changes'&&!notes.value.trim()){error.value='请先写下需要修改的地方';return}busy.value=true;error.value='';try{task.value=await api.reviewProduction(value.id,kind,decision,value.storyVersionId,value.media.videoSha256,notes.value)}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
onLoad(q=>{id.value=String(q?.id||'')});onShow(()=>{visible=true;void load()});onHide(()=>{visible=false;stop()});onUnload(()=>{visible=false;stop()})
</script>
<template><FeatureLayout title="声音与分镜制作" :subtitle="story?.title"><view class="page-content">
  <view v-if="error" class="paper-panel section-gap"><text class="error-copy" role="alert">{{error}}</text><button class="outline-button full-button" @tap="load">重新加载</button></view>
  <template v-if="options&&context">
    <view class="paper-panel"><text class="section-title serif">为人物选择音色</text><view v-for="role in context.roles" :key="role.id" class="voice-row"><text>{{role.name}}</text><picker :range="options.voices" range-key="name" :value="Math.max(0,options.voices.findIndex(v=>v.id===voices[role.id]))" :disabled="busy||!!task&&!finished" @change="voices[role.id]=options.voices[Number($event.detail.value)].id"><view class="voice-choice">{{options.voices.find(v=>v.id===voices[role.id])?.name||'请选择'}}　›</view></picker></view><text class="small-note spaced">本次使用系统音色。角色音色保持固定，情绪与语气逐句变化。</text></view>
    <view class="paper-panel section-gap"><text class="section-title serif">本次画面方案</text><text class="copy">{{context.presentation}}</text><text v-for="(scene,index) in context.scenes" :key="scene.id" class="scene-copy">{{index+1}}. {{scene.title}} · {{scene.events}} 条原文事件</text><text class="small-note spaced">按原场次和事件顺序分批编排；配音时长按实际音频测量。此版本不表现精细肢体动作。</text></view>
    <view v-if="task" class="paper-panel section-gap"><text class="section-title serif">{{task.status==='failed'?'制作暂时停下':task.media?'预览已就绪':'正在制作'}}</text><text class="copy">{{task.message}}</text><progress :percent="task.progress" activeColor="#cf502a" :stroke-width="5"/><text class="small-note spaced">{{task.progress}}% · 可以离开，稍后从故事详情返回</text><text v-if="task.status==='failed'" class="error-copy">{{task.errorCode}}</text><button v-if="task.status==='failed'" class="warm-button full-button" :loading="busy" :disabled="busy" @tap="retry">恢复当前制作</button></view>
    <button v-if="!task||changed&&finished" class="warm-button full-button" :disabled="busy||!options.credentialConfigured" :loading="busy" @tap="start">{{task?'按新音色创建制作版本':'按此方案制作真实配音与分镜'}}</button>
    <text v-if="!task||changed" class="small-note spaced">制作会调用真实音频模型并消耗额度。新建版本保留旧制品；同一任务恢复会复用已生成素材。</text>
    <view v-if="task?.media" class="paper-panel section-gap"><text class="section-title serif">试听与预览审核</text><text class="copy">实测 {{task.media.duration.toFixed(2)}} 秒 · 配音、音效及原文动作卡</text><video id="production-review-video" class="review-video" :src="task.media.videoUrl" :poster="task.media.posterUrl" controls object-fit="contain"/><button class="outline-button full-button" @tap="goPage('performance',{id})">打开演绎播放器</button>
      <text class="field-label">声音审核 · {{task.audioReview==='approved'?'已通过':task.audioReview==='changes_requested'?'需修改':'待试听'}}</text><label class="check-row"><checkbox :checked="listened" color="#cf502a" @tap="listened=!listened"/><text>我已试听完整配音、音效与同步效果</text></label><button class="warm-button full-button" :disabled="busy||!listened" @tap="review('audio','approve')">确认本次声音效果</button>
      <text class="field-label spaced">视觉审核 · {{task.visualReview==='approved'?'已通过':task.visualReview==='changes_requested'?'需修改':'待审阅'}}</text><label class="check-row"><checkbox :checked="watched" color="#cf502a" @tap="watched=!watched"/><text>我已查看分镜、字幕、动作卡和场景方案</text></label><button class="warm-button full-button" :disabled="busy||!watched" @tap="review('visual','approve')">确认本次分镜效果</button>
      <textarea v-model="notes" class="form-textarea spaced" placeholder="需要修改的读音、情绪、场景或画面问题" maxlength="1000"/><view class="review-actions"><button class="outline-button" :disabled="busy" @tap="review('audio','changes')">声音需修改</button><button class="outline-button" :disabled="busy" @tap="review('visual','changes')">视觉需修改</button></view><text class="small-note spaced">审核绑定当前故事版本和视频制品。确认后回写原制作工作流并冻结本地审核制品；不会对外发布。修改意见不会自动触发付费生成。</text>
    </view>
  </template><text v-else-if="!error" class="copy">正在读取真实剧本与制作配置…</text>
</view></FeatureLayout></template>
<style scoped>.voice-row{display:flex;align-items:center;justify-content:space-between;gap:20rpx;padding:25rpx 0;border-bottom:2rpx solid #eadcc9}.voice-choice{padding:12rpx;color:#995b36;font-size:26rpx}.scene-copy{display:block;margin-top:20rpx;color:#77563b}.review-video{width:100%;height:360rpx;margin-top:25rpx;background:#211a16;border-radius:18rpx}.check-row{display:flex;align-items:center;gap:14rpx;font-size:26rpx;margin-top:20rpx;line-height:1.7}.review-actions{display:flex;gap:18rpx;margin-top:20rpx}.review-actions button{flex:1;padding:20rpx 10rpx}</style>
